css:
.token-base { position: absolute; display: flex; flex-direction: column; width: 210px; height: 110px; padding: 10px; box-sizing: border-box; text-align: center; justify-content: center; z-index: 2; }
.token-base.tall { height: 145px; }
.token-base.short { height: 80px; }
.token-base.compact { width: 160px; height: 60px; padding: 6px 8px; }
.token-green { background-color: var(--ps-orgchart-green-bg); border: 2px solid var(--ps-orgchart-green); border-radius: 0; }
.token-blue { background-color: var(--ps-orgchart-blue-bg); border: 2px solid var(--ps-orgchart-blue); border-radius: 0; }
.token-purple { background-color: var(--ps-orgchart-purple-bg); border: 2px solid var(--ps-orgchart-purple); border-radius: 0; }
.token-orange { background-color: var(--ps-orgchart-orange-bg); border: 2px solid var(--ps-orgchart-orange); border-radius: 0; }
.token-grey { background-color: var(--ps-orgchart-grey-bg); border: 2px solid var(--ps-orgchart-grey); border-radius: 0; }
.token-yellow { position: absolute; display: flex; flex-direction: column; width: 250px; height: 110px; padding: 12px; box-sizing: border-box; text-align: center; justify-content: center; z-index: 2; background-color: var(--ps-orgchart-yellow-bg); border: 2px dashed var(--ps-orgchart-yellow); border-radius: 110px; }
.token-orange-ellipse-dashed { position: absolute; display: flex; flex-direction: column; width: 210px; height: 90px; padding: 10px; box-sizing: border-box; text-align: center; justify-content: center; z-index: 2; background-color: var(--ps-orgchart-orange-bg); border: 2px dashed var(--ps-orgchart-orange); border-radius: 110px; }
.t-title { font-size: 12px; font-weight: 800; letter-spacing: -0.01em; line-height: 1.2; margin: 0; }
.t-alias { font-size: 10px; font-style: italic; color: var(--ps-ink-secondary); margin: 2px 0 0; }
.t-node { font-size: 10px; font-weight: 700; color: var(--ps-ink-secondary); margin: 4px 0 0; }
